css:
:root { color: var(--textPrimary); background: var(--appBackground); font-synthesis: none; -webkit-font-smoothing: antialiased; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 15px; line-height: 1.55; }
* { box-sizing: border-box; }
body { user-select: none; cursor: default; margin: 0px; }
.artifact-blocks, .source-card blockquote, .translated, .focus-title, .focus-summary, .calculation-result, .meeting-review ul, .selectable-text, [role="alert"], input, textarea, [contenteditable="true"] { user-select: text; }
button, summary, label, .provenance { user-select: none; }
button svg { pointer-events: none; }
select, summary, label.check { cursor: pointer; }
select[aria-disabled="true"] { cursor: progress; }
.settings-field-hint { color: var(--textSecondary); margin: -4px 0px 18px; font-size: 13px; }
button, input, select, textarea { font: inherit; color: inherit; }
button { border: 1px solid var(--controlBorder); background: var(--contentSurface); cursor: pointer; border-radius: 10px; justify-content: center; align-items: center; gap: 8px; min-height: 38px; padding: 8px 14px; font-weight: 500; line-height: 1.4; transition: background-color 0.15s, border-color 0.15s; display: inline-flex; }
button svg { flex-shrink: 0; }
button:hover:not(:disabled) { background: var(--subtleSurface); border-color: var(--textSecondary); }
button:disabled { color: var(--disabledText); opacity: 0.65; cursor: default; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.primary { background: var(--accent); color: rgb(255, 255, 255); border-color: var(--accent); min-height: 44px; padding: 10px 20px; box-shadow: rgba(16, 24, 40, 0.05) 0px 1px 2px; }
.primary:hover:not(:disabled) { background: rgb(29, 82, 183); border-color: rgb(29, 82, 183); }
.primary:disabled { color: rgb(255, 255, 255); }
.danger { color: var(--error); background: var(--errorSurface); border-color: rgba(0, 0, 0, 0); }
.danger:hover:not(:disabled) { border-color: var(--error); background: var(--errorSurface); }
.text-button, .source-link, .cite { color: var(--accent); box-shadow: none; background: 0px 0px; border-color: rgba(0, 0, 0, 0); padding: 6px 8px; }
.text-button:hover, .source-link:hover, .cite:hover { background: var(--accentSubtle); border-color: rgba(0, 0, 0, 0); }
.source-link { min-height: 30px; font-size: 13px; }
.cite { float: right; min-height: 28px; padding: 2px 6px; }
h1 { letter-spacing: -0.8px; overflow-wrap: anywhere; margin: 14px 0px 16px; font-size: 32px; font-weight: 600; line-height: 1.25; }
h2 { letter-spacing: -0.35px; margin: 0px 0px 12px; font-size: 21px; font-weight: 600; line-height: 1.35; }
h3 { font-size: 16px; font-weight: 600; }
p { margin: 8px 0px 16px; }
small, .muted, .eyebrow, .section-label { color: var(--textTertiary); }
small, .eyebrow, .section-label { font-size: 12px; }
.eyebrow, .section-label { align-items: center; gap: 8px; display: flex; }
.lead { color: var(--textSecondary); max-width: 760px; font-size: 17px; line-height: 1.7; }
.app-shell { min-height: 100vh; padding-bottom: 48px; }
.toolbar { border-bottom: 1px solid var(--divider); background: var(--contentSurface); flex-wrap: wrap; align-items: center; gap: 16px; min-height: 64px; padding: 12px 28px; display: flex; }
.brand { letter-spacing: -0.3px; white-space: nowrap; align-items: center; gap: 10px; font-weight: 600; display: flex; }
.brand-mark { background: var(--accent); color: rgb(255, 255, 255); border-radius: 10px; place-items: center; width: 32px; height: 32px; display: grid; }
.brand-subtitle { color: var(--textTertiary); border-left: 1px solid var(--divider); font-size: 12px; }
.toolbar-divider { border-left: 1px solid var(--divider); height: 20px; }
.meeting-name { text-overflow: ellipsis; white-space: nowrap; text-align: left; max-width: 350px; color: var(--textPrimary); font-weight: 600; display: block; overflow: hidden; }
.back-button { color: var(--textSecondary); }
.toolbar-actions { align-items: center; gap: 8px; margin-left: auto; display: flex; }
.toolbar-actions > .text-button { color: var(--textSecondary); width: 36px; padding: 8px; }
.status { color: var(--textSecondary); background: var(--subtleSurface); white-space: nowrap; border-radius: 6px; align-items: center; gap: 7px; padding: 5px 9px; font-size: 12px; font-weight: 500; display: inline-flex; }
.status-capturing { color: var(--listening); background: var(--successSurface); }
.status-paused, .status-starting { color: var(--warning); background: var(--warningSurface); }
.status-input_error { color: var(--error); background: var(--errorSurface); }
.dot { background: var(--textTertiary); border-radius: 50%; flex-shrink: 0; width: 6px; height: 6px; display: inline-block; }
.dot.capturing { background: var(--listening); }
.dot.paused, .dot.starting { background: var(--warning); }
.dot.input_error { background: var(--error); }
.library { max-width: 1120px; margin: auto; padding: 48px 32px 40px; }
.home-hero { border: 1px solid var(--divider); background: var(--contentSurface); border-radius: 18px; padding: 44px 48px 36px; box-shadow: rgba(16, 24, 40, 0.008) 0px 2px 5px; }
.hero-kicker { color: var(--accent); align-items: center; gap: 8px; margin-bottom: 14px; font-size: 13px; font-weight: 500; display: inline-flex; }
.home-hero h1 { max-width: 660px; margin-top: 0px; }
.home-hero .lead { max-width: 650px; margin: 0px; }
.start-row { flex-wrap: wrap; align-items: center; gap: 28px; margin-top: 30px; display: flex; }
.start-button { gap: 12px; min-height: 48px; padding: 12px 22px; }
.start-button svg:last-child { margin-left: 16px; }
.device-summary { color: var(--textSecondary); font-size: 13px; }
.device-summary > div { align-items: center; gap: 7px; display: flex; }
.device-summary .source-link { min-height: 26px; color: var(--textTertiary); gap: 6px; padding: 2px 0px; font-size: 12px; }
.hero-footnote { color: var(--textTertiary); margin: 24px 0px 0px; font-size: 12px; }
.setup-note { background: var(--warningSurface); color: var(--warning); border-radius: 10px; flex-wrap: wrap; align-items: center; gap: 12px; margin: 20px 0px; padding: 16px 20px; font-size: 13px; display: flex; }
.setup-note strong { font-weight: 600; }
.setup-note p { flex: 1 1 0%; min-width: 200px; margin: 0px; }
.setup-note .source-link { color: var(--warning); }
.recent-meetings { margin-top: 40px; }
.recent-heading { justify-content: space-between; align-items: center; gap: 16px; margin: 0px 2px 16px; display: flex; }
.recent-heading h2 { margin: 0px; font-size: 18px; }
.recent-heading > span { color: var(--textTertiary); font-size: 12px; }
.meeting-list { background: var(--contentSurface); border: 1px solid var(--divider); border-radius: 14px; overflow: hidden; }
.meeting-row { border-top: 0px; border-right: 0px; border-left: 0px; border-image: none; border-bottom: 1px solid var(--subtleDivider); text-align: left; border-radius: 0px; justify-content: flex-start; gap: 18px; width: 100%; min-height: 88px; padding: 20px 24px; }
.meeting-row:last-child { border-bottom: 0px; }
.meeting-row:hover { background: var(--selectedSurface); }
.meeting-file, .quiet-icon { width: 42px; height: 44px; color: var(--textTertiary); background: var(--subtleSurface); border: 1px solid var(--subtleDivider); border-radius: 10px; flex-shrink: 0; place-items: center; display: grid; }
.meeting-file.is-active { color: var(--accent); background: var(--accentSubtle); }
.meeting-row-content { flex: 1 1 0%; min-width: 0px; }
.meeting-row strong { overflow-wrap: anywhere; font-weight: 500; }
.meeting-row p { color: var(--textTertiary); flex-wrap: wrap; align-items: center; gap: 7px; margin: 7px 0px 0px; font-size: 12px; font-weight: 400; display: flex; }
.row-chevron { color: var(--textTertiary); }
.library-empty { border: 1px dashed var(--divider); border-radius: 14px; align-items: center; gap: 18px; padding: 32px; display: flex; }
.library-empty strong { font-size: 14px; font-weight: 500; }
.library-empty p { color: var(--textTertiary); margin: 5px 0px 0px; font-size: 13px; }
.library > details { color: var(--textTertiary); font-size: 12px; }
.workspace-meta { justify-content: space-between; align-items: center; gap: 16px; max-width: 1120px; margin: auto; padding: 22px 4px 16px; font-size: 12px; display: flex; }
.meta-actions { flex-wrap: wrap; gap: 8px; display: flex; }
.meta-actions button { color: var(--textSecondary); min-height: 32px; font-size: 12px; }
.workspace { border: 1px solid var(--divider); background: var(--contentSurface); border-radius: 16px; max-width: 1120px; min-height: 480px; margin: 0px auto; padding: 36px 40px; box-shadow: rgba(16, 24, 40, 0.008) 0px 2px 5px; }
.focus-label { color: var(--accent); align-items: center; gap: 7px; font-weight: 500; display: inline-flex; }
.focus-title { max-width: 940px; margin-top: 14px; }
.focus-summary { margin-bottom: 28px; }
.artifact-blocks { margin-top: 32px; }
.artifact-blocks.columns { grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 28px; display: grid; }
.expression { border-top: 1px solid var(--subtleDivider); min-width: 0px; margin-bottom: 32px; padding-top: 24px; transition: background-color 0.18s; }
.expression-heading { justify-content: space-between; align-items: start; gap: 16px; display: flex; }
.expression-heading h2 { margin: 0px; font-size: 20px; }
.expression-heading .source-link { flex-shrink: 0; margin-top: -3px; }
.provenance { color: var(--textTertiary); flex-wrap: wrap; align-items: center; gap: 10px; margin: 10px 0px 20px; font-size: 12px; display: flex; }
.provenance .semantic-state { color: var(--warning); background: var(--warningSurface); border-radius: 5px; padding: 2px 7px; }
.provenance .state-confirmed { color: var(--listening); background: var(--successSurface); }
.provenance .state-disputed { color: var(--error); background: var(--errorSurface); }
.plain-list { padding: 0px; list-style: none; }
.expression ul:not(.plain-list) { padding-left: 22px; }
.expression li { margin-bottom: 12px; }
.expression-changed { background-color: var(--selectedSurface); }
.table-scroll { border: 1px solid var(--divider); border-radius: 10px; overflow-x: auto; }
table { border-collapse: collapse; text-align: left; width: 100%; font-size: 14px; }
th, td { border-bottom: 1px solid var(--subtleDivider); vertical-align: top; overflow-wrap: anywhere; min-width: 130px; padding: 16px 18px; }
th { background: var(--subtleSurface); color: var(--textSecondary); font-weight: 600; }
td:first-child { color: var(--textSecondary); font-weight: 500; }
tbody tr:last-child td { border-bottom: 0px; }
tbody tr:hover { background: var(--subtleSurface); }
.timeline { padding: 0px; list-style: none; }
.timeline li { border-left: 2px solid var(--divider); grid-template-columns: 150px 1fr; gap: 24px; padding: 12px 0px 20px 20px; display: grid; }
.time-label { color: var(--textSecondary); }
.bar-row { grid-template-columns: minmax(80px, 1fr) 2fr minmax(80px, 1fr); align-items: center; gap: 12px; margin: 16px 0px; font-size: 13px; display: grid; }
.bar-track { background: var(--accentSubtle); border-radius: 4px; height: 12px; }
.bar { background: var(--accent); border-radius: 3px; height: 12px; }
.diverging { position: relative; }
.diverging::before { content: ""; border-left: 1px solid var(--textSecondary); height: 100%; position: absolute; left: 50%; }
.generated-frame { border: 1px solid var(--divider); background: var(--contentSurface); border-radius: 10px; width: 100%; height: 390px; }
.changes { background: var(--subtleSurface); border-radius: 10px; margin: 28px 0px 20px; padding: 18px 20px; }
.changes .section-label { color: var(--textSecondary); margin: 0px 0px 12px; font-weight: 600; }
.changes p { color: var(--textSecondary); margin: 8px 0px; padding-left: 23px; font-size: 14px; }
.empty-work { text-align: center; flex-direction: column; justify-content: center; align-items: center; max-width: 600px; min-height: 360px; margin: auto; padding: 40px 12px; display: flex; }
.empty-symbol { background: var(--accentSubtle); width: 68px; height: 68px; color: var(--accent); border-radius: 20px; place-items: center; margin-bottom: 20px; display: grid; }
.empty-work h1 { font-size: 25px; }
.empty-work p { color: var(--textSecondary); max-width: 420px; }
.manual-input { border-top: 1px dashed var(--divider); margin-top: 28px; padding-top: 16px; }
.manual-input textarea { margin: 8px 0px 12px; }
.explore-entry { margin: 24px 0px 0px; }
.explore-toggle { color: var(--accent); background: var(--accentSubtle); border-color: rgba(0, 0, 0, 0); }
.explore-toggle:hover { border-color: var(--accent); background: var(--accentSubtle); }
.explore-toggle .rotated { transform: rotate(90deg); }
.ask-bar { border: 1px solid var(--accent); background: var(--contentSurface); box-shadow: 0 0 0 3px var(--accentSubtle); border-radius: 12px; flex-wrap: wrap; align-items: center; gap: 12px; margin: 14px 0px 28px; padding: 18px 20px; display: flex; }
.ask-bar textarea { resize: vertical; border: 0px; flex: 1 1 0%; min-width: 160px; min-height: 48px; max-height: 160px; margin: 0px; padding: 8px 0px; }
.ask-bar > button { white-space: nowrap; }
.explore-note, .scope-note { color: var(--textSecondary); font-size: 12px; }
.explore-note { flex-basis: 100%; margin: 0px; }
.context-chip { border: 1px solid var(--divider); background: var(--subtleSurface); max-width: 100%; color: var(--textSecondary); border-radius: 6px; align-items: center; gap: 7px; padding: 3px 6px 3px 8px; font-size: 12px; display: inline-flex; }
.context-chip > span { text-overflow: ellipsis; white-space: nowrap; overflow: hidden; }
.context-chip button { background: 0px 0px; border: 0px; min-height: 24px; padding: 3px; }
.ask-context-note { color: var(--warning); flex-basis: 100%; margin: 0px; font-size: 12px; }
.banner { border-radius: 10px; justify-content: space-between; align-items: center; gap: 20px; max-width: 1120px; margin: 16px auto; padding: 12px 18px; font-size: 13px; display: flex; }
.banner.error { background: var(--errorSurface); color: var(--error); }
.banner.warning { background: var(--warningSurface); color: var(--warning); }
.warning-text, .stale { color: var(--warning); }
.error-text { color: var(--error); }
.update-notice { background: var(--accentSubtle); border-radius: 10px; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 24px; padding: 12px 16px; font-size: 13px; display: flex; }
.version-list { gap: 10px; max-width: 1120px; margin: 0px auto 16px; display: flex; overflow: auto; }
.version-list button { white-space: nowrap; font-size: 12px; }
.artifact-actions, .button-row { flex-wrap: wrap; gap: 12px; display: flex; }
.artifact-actions { margin-top: 20px; }
.artifact-actions button { font-size: 13px; }
.source-drawer { background: var(--contentSurface); border-left: 1px solid var(--divider); z-index: 5; width: 400px; max-width: 94vw; padding: 28px; position: fixed; top: 0px; bottom: 0px; right: 0px; overflow: auto; box-shadow: rgba(16, 24, 40, 0.04) -8px 0px 32px; }
.source-drawer[hidden] { display: none; }
.drawer-intro { color: var(--textTertiary); border-bottom: 1px solid var(--divider); padding-bottom: 20px; font-size: 13px; }
.source-card { border-bottom: 1px solid var(--divider); padding: 20px 0px; }
.source-card .muted { margin-top: 12px; font-size: 13px; }
.source-card blockquote { background: var(--subtleSurface); border-left: 2px solid var(--accent); white-space: pre-wrap; overflow-wrap: anywhere; border-radius: 0px 8px 8px 0px; margin: 10px 0px 14px; padding: 16px; font-size: 15px; line-height: 1.75; }
.source-original-label { color: var(--textSecondary); font-size: 12px; font-weight: 600; }
.source-card .source-link { margin-top: 8px; }
.source-card form { background: var(--subtleSurface); border-radius: 10px; margin-top: 12px; padding: 1px 16px 16px; }
.translated { border: 1px solid var(--divider); border-radius: 8px; margin-top: 12px; padding: 12px; }
.modal-backdrop { z-index: 10; background: rgba(16, 24, 40, 0.22); justify-content: center; align-items: center; padding: 24px; display: flex; position: fixed; inset: 0px; }
.modal { background: var(--contentSurface); border: 1px solid var(--divider); border-radius: 18px; width: 560px; max-width: 100%; max-height: calc(100dvh - 48px); padding: 28px; overflow: auto; box-shadow: rgba(16, 24, 40, 0.15) 0px 20px 80px; }
.modal-title { justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 20px; display: flex; }
.modal-title h2 { align-items: center; gap: 9px; margin: 0px; display: flex; }
.modal-title button { background: var(--subtleSurface); min-height: 32px; color: var(--textSecondary); border: 0px; padding: 8px; }
label { margin: 18px 0px 12px; font-size: 13px; font-weight: 500; display: block; }
input, select, textarea { border: 1px solid var(--controlBorder); background: var(--contentSurface); border-radius: 8px; width: 100%; min-width: 0px; min-height: 42px; margin-top: 7px; padding: 10px 12px; font-weight: 400; display: block; }
textarea { resize: vertical; min-height: 96px; }
input[type="checkbox"] { width: 16px; height: 16px; min-height: 16px; accent-color: var(--accent); flex-shrink: 0; margin: 2px 0px 0px; }
.check { align-items: flex-start; gap: 12px; display: flex; }
.privacy { color: var(--textTertiary); margin: 20px 0px; font-size: 12px; line-height: 1.7; }
.settings-modal { flex-direction: column; width: 780px; padding: 0px; display: flex; overflow: hidden; }
.settings-modal > .modal-title { margin-bottom: 8px; padding: 24px 28px 0px; }
.settings-intro { color: var(--textTertiary); margin: 0px; padding: 0px 28px 20px; font-size: 13px; }
.settings-layout { border-top: 1px solid var(--divider); grid-template-columns: 164px minmax(0px, 1fr); min-height: 0px; display: grid; }
.settings-nav { background: var(--subtleSurface); border-right: 1px solid var(--divider); flex-direction: column; gap: 8px; padding: 20px 12px; display: flex; }
.settings-nav button { color: var(--textSecondary); background: 0px 0px; border: 0px; justify-content: flex-start; padding: 10px; font-size: 13px; }
.settings-nav button:hover, .settings-nav button:focus { color: var(--accent); background: var(--accentSubtle); }
.settings-content { overscroll-behavior: contain; padding: 0px 28px 24px; overflow: auto; }
.settings-section { border-top: 1px solid var(--divider); margin: 24px 0px 0px; padding-top: 8px; scroll-margin-top: 20px; font-size: 13px; }
.settings-section:first-child { border: 0px; margin-top: 0px; }
.settings-section h3 { align-items: center; gap: 8px; display: flex; }
.settings-section h3 svg { color: var(--textTertiary); }
.settings-diagnostics { color: var(--textTertiary); font-size: 12px; }
.settings-diagnostics p { overflow-wrap: anywhere; }
.settings-footer { border-top: 1px solid var(--divider); background: var(--contentSurface); justify-content: space-between; align-items: center; gap: 16px; padding: 16px 28px; display: flex; }
.settings-footer .settings-save-status { overflow-wrap: anywhere; min-width: 0px; color: var(--textTertiary); font-size: 12px; }
.scenario-editor { border-top: 1px solid var(--divider); padding: 24px 0px; }
.scenario-editor h2 { margin-top: 8px; }
.scenario-editor > p { color: var(--textSecondary); font-size: 13px; }
.scenario-editor code { overflow-wrap: anywhere; color: var(--textSecondary); background: var(--subtleSurface); border-radius: 8px; padding: 12px; font-size: 12px; display: block; }
.parameters { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 20px; margin: 8px 0px 24px; display: grid; }
.calculation-result { background: var(--accentSubtle); border-radius: 10px; justify-content: space-between; align-items: center; gap: 18px; margin-top: 20px; padding: 18px; display: flex; }
.saved-record { border-bottom: 1px solid var(--divider); margin: 12px 0px; padding: 16px 0px; }
.saved-record p { font-size: 13px; }
.badge { background: var(--accentSubtle); border-radius: 5px; padding: 4px 8px; font-size: 12px; }
details { margin-top: 24px; }
summary { cursor: pointer; }
.evidence-list { max-height: 230px; overflow: auto; }
.launcher { color: rgb(255, 255, 255); user-select: none; touch-action: none; width: 44px; height: 44px; min-height: 44px; box-shadow: none; isolation: isolate; background: 0px 0px; border: 0px; border-radius: 13px; padding: 0px; position: relative; overflow: hidden; }
.launcher:hover { background: 0px 0px; }
.launcher-artwork { border-radius: inherit; pointer-events: none; position: absolute; inset: 0px; overflow: hidden; }
.launcher-artwork img { object-fit: cover; width: 120%; max-width: none; height: 120%; position: absolute; top: -10%; left: -10%; }
.launcher:hover .launcher-artwork { filter: brightness(1.08); }
.launcher:focus-visible { outline: none; }
.launcher:focus-visible::after { content: ""; pointer-events: none; border: 2px solid rgb(159, 192, 255); border-radius: 11px; position: absolute; inset: 2px; }
.launcher-indicator { color: rgb(23, 45, 99); pointer-events: none; background: rgb(168, 181, 206); border-radius: 50%; place-items: center; width: 10px; height: 10px; display: grid; position: absolute; top: 3px; right: 3px; box-shadow: rgb(32, 61, 123) 0px 0px 0px 1.5px; }
.launcher-indicator.connecting { background: rgb(32, 61, 123); border: 2px solid rgb(255, 203, 112); }
.launcher-indicator.listening { background: rgb(74, 222, 164); }
.launcher-indicator.paused { background: rgb(255, 203, 112); }
.launcher-indicator.error { background: rgb(255, 135, 144); }
.indicator-error-mark { font-size: 9px; font-weight: 800; line-height: 1; }
.launcher-status-listening { color: var(--listening); background: var(--successSurface); }
.launcher-status-connecting, .launcher-status-paused { color: var(--warning); background: var(--warningSurface); }
.launcher-status-error { color: var(--error); background: var(--errorSurface); }
html[data-role="launcher"], html[data-role="launcher"] body, html[data-role="launcher"] #root { background: 0px 0px; width: 44px; height: 44px; overflow: hidden; }
.preview { border: 1px solid var(--divider); background: rgba(255, 255, 255, 0.96); border-radius: 14px; height: 230px; padding: 20px; font-size: 13px; overflow: auto; }
.preview h2 { margin: 12px 0px; font-size: 18px; }
.preview p { color: var(--textSecondary); margin: 5px 0px; font-size: 12px; }
.preview button { margin-top: 12px; font-size: 12px; }
.preview .eyebrow { flex-wrap: wrap; gap: 6px; display: flex; }
.reduce-motion * { scroll-behavior: auto !important; transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
.reduce-transparency .preview, .reduce-transparency .toolbar { background: var(--contentSurface); backdrop-filter: none; }
body[data-role="launcher"], body[data-role="preview"] { background: 0px 0px; overflow: hidden; }
.relationship-scroll { overscroll-behavior: contain; background: var(--subtleSurface); border: 1px solid var(--subtleDivider); border-radius: 12px; max-width: 100%; padding: 16px; overflow: auto; }
